using EmployeeMonitoringAPI.Data;
using EmployeeMonitoringAPI.DTOs;
using EmployeeMonitoringAPI.Interfaces;
using EmployeeMonitoringAPI.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Security.Claims;
namespace EmployeeMonitoringAPI.Controllers;
[Route("api/[controller]")][ApiController][Authorize]
public sealed class ProjectsController:ControllerBase
{
 private readonly ApplicationDbContext _db;private readonly IAuditService _audit;
 public ProjectsController(ApplicationDbContext db,IAuditService audit){_db=db;_audit=audit;}
 [HttpGet]
 public async Task<IActionResult> List(bool includeArchived=false,string? search=null,string? status=null,int? departmentId=null,int? managerId=null){var q=_db.Projects.AsNoTracking().AsQueryable();if(!includeArchived)q=q.Where(x=>!x.IsArchived);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.ProjectName.Contains(search)||x.ProjectCode.Contains(search));if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);if(departmentId.HasValue)q=q.Where(x=>x.DepartmentId==departmentId);if(managerId.HasValue)q=q.Where(x=>x.ManagerId==managerId);return Ok(await q.OrderByDescending(x=>x.CreatedAt).Select(x=>new{x.ProjectId,x.ProjectName,x.ProjectCode,x.Description,x.DepartmentId,DepartmentName=x.Department!=null?x.Department.Name:null,x.Status,x.Priority,x.ProgressPercentage,x.StartDate,x.EndDate,x.ManagerId,ManagerName=x.Manager!=null?x.Manager.FullName:null,x.IsArchived,x.CreatedAt,x.UpdatedAt,TeamSize=_db.ProjectAssignments.Count(a=>a.ProjectId==x.ProjectId)}).ToListAsync());}
 [HttpGet("{id:int}")]
 public async Task<IActionResult> Get(int id){var x=await _db.Projects.AsNoTracking().Include(p=>p.Manager).Include(p=>p.Department).FirstOrDefaultAsync(p=>p.ProjectId==id);return x is null?NotFound(new{message="Project not found"}):Ok(x);}
 [HttpPost][Authorize(Roles="Admin")]
 public async Task<IActionResult> Create(ProjectRequest dto){var validation=await Validate(dto,null);if(validation is not null)return validation;var item=new Project{ProjectName=dto.ProjectName.Trim(),ProjectCode=dto.ProjectCode.Trim().ToUpperInvariant(),Description=dto.Description.Trim(),DepartmentId=dto.DepartmentId,Status=dto.Status,Priority=dto.Priority,StartDate=dto.StartDate,EndDate=dto.EndDate,ProgressPercentage=dto.ProgressPercentage,ManagerId=dto.ManagerId,CreatedAt=DateTime.UtcNow,UpdatedAt=DateTime.UtcNow};_db.Projects.Add(item);await _db.SaveChangesAsync();await _audit.RecordAsync("ProjectCreated","Project",item.ProjectId.ToString(),safeMetadata:new{item.ProjectName,item.ProjectCode,item.ManagerId});return Ok(new{message="Project created",item.ProjectId});}
 [HttpPut("{id:int}")][Authorize(Roles="Admin")]
 public async Task<IActionResult> Update(int id,ProjectRequest dto){var item=await _db.Projects.FindAsync(id);if(item is null)return NotFound(new{message="Project not found"});if(item.IsArchived)return Conflict(new{message="Archived projects must be restored before editing"});var validation=await Validate(dto,id);if(validation is not null)return validation;if(item.Status!=dto.Status)_db.ProjectHistories.Add(new ProjectHistory{ProjectId=id,OldStatus=item.Status,NewStatus=dto.Status,UpdatedAt=DateTime.UtcNow});item.ProjectName=dto.ProjectName.Trim();item.ProjectCode=dto.ProjectCode.Trim().ToUpperInvariant();item.Description=dto.Description.Trim();item.DepartmentId=dto.DepartmentId;item.Status=dto.Status;item.Priority=dto.Priority;item.StartDate=dto.StartDate;item.EndDate=dto.EndDate;item.ProgressPercentage=dto.ProgressPercentage;item.ManagerId=dto.ManagerId;item.UpdatedAt=DateTime.UtcNow;await _db.SaveChangesAsync();await _audit.RecordAsync("ProjectUpdated","Project",id.ToString(),safeMetadata:new{item.Status,item.ProgressPercentage,item.ManagerId});return Ok(new{message="Project updated"});}
 [HttpPut("{id:int}/archive")][Authorize(Roles="Admin")]
 public async Task<IActionResult> Archive(int id){var x=await _db.Projects.FindAsync(id);if(x is null)return NotFound(new{message="Project not found"});if(x.IsArchived)return Conflict(new{message="Project is already archived"});x.IsArchived=true;x.UpdatedAt=DateTime.UtcNow;await _db.SaveChangesAsync();await _audit.RecordAsync("ProjectArchived","Project",id.ToString());return Ok(new{message="Project archived"});}
 [HttpPut("{id:int}/restore")][Authorize(Roles="Admin")]
 public async Task<IActionResult> Restore(int id){var x=await _db.Projects.FindAsync(id);if(x is null)return NotFound(new{message="Project not found"});if(!x.IsArchived)return Conflict(new{message="Project is not archived"});x.IsArchived=false;x.UpdatedAt=DateTime.UtcNow;await _db.SaveChangesAsync();await _audit.RecordAsync("ProjectRestored","Project",id.ToString());return Ok(new{message="Project restored"});}
 [HttpDelete("{id:int}")][Authorize(Roles="Admin")]
 public async Task<IActionResult> Delete(int id){var x=await _db.Projects.FindAsync(id);if(x is null)return NotFound(new{message="Project not found"});var dependent=await _db.ProjectAssignments.AnyAsync(a=>a.ProjectId==id)||await _db.WorkTasks.AnyAsync(t=>t.ProjectId==id)||await _db.ProjectHistories.AnyAsync(h=>h.ProjectId==id)||await _db.CalendarEvents.AnyAsync(e=>e.ProjectId==id);if(dependent)return Conflict(new{message="Project has historical or dependent records and must be archived"});_db.Projects.Remove(x);await _db.SaveChangesAsync();await _audit.RecordAsync("ProjectDeleted","Project",id.ToString());return Ok(new{message="Accidental project permanently deleted"});}
 [HttpPost("{projectId:int}/assign")][Authorize(Roles="Manager")]
 public async Task<IActionResult> Assign(int projectId,ProjectAssignmentRequestDto dto)=>await AssignInternal(projectId,dto.EmployeeId!=0?dto.EmployeeId:dto.UserId.GetValueOrDefault());
 [HttpPost("{projectId:int}/assign/{userId:int}")][Authorize(Roles="Manager")]
 public async Task<IActionResult> Assign(int projectId,int userId)=>await AssignInternal(projectId,userId);
 [HttpGet("my-projects")][Authorize(Roles="Employee,Manager,HR")]
 public async Task<IActionResult> Mine(){var id=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);return Ok(await _db.ProjectAssignments.AsNoTracking().Where(x=>x.UserId==id&&x.Project!=null&&!x.Project.IsArchived).Select(x=>new{x.Project!.ProjectId,x.Project.ProjectName,x.Project.ProjectCode,x.Project.Description,x.Project.Status,x.Project.ProgressPercentage,x.Project.StartDate,x.Project.EndDate}).ToListAsync());}
 [HttpGet("{projectId:int}/members")]
 public async Task<IActionResult> Members(int projectId){return Ok(await _db.ProjectAssignments.AsNoTracking().Where(x=>x.ProjectId==projectId).Select(x=>new{x.User!.UserId,x.User.FullName,x.User.Email,x.User.Role,x.AssignedAt}).ToListAsync());}
 [HttpGet("history/{projectId:int}")]
 public async Task<IActionResult> History(int projectId)=>Ok(await _db.ProjectHistories.AsNoTracking().Where(x=>x.ProjectId==projectId).OrderByDescending(x=>x.UpdatedAt).ToListAsync());
 private async Task<IActionResult?> Validate(ProjectRequest dto,int? id){if(dto.EndDate<dto.StartDate)return BadRequest(new{message="End date must be on or after start date"});var code=dto.ProjectCode.Trim().ToUpperInvariant();if(await _db.Projects.AnyAsync(x=>(!id.HasValue||x.ProjectId!=id)&&x.ProjectCode==code))return Conflict(new{message="Project code already exists"});if(dto.DepartmentId.HasValue&&!await _db.Departments.AnyAsync(x=>x.Id==dto.DepartmentId&&x.IsActive))return BadRequest(new{message="Project department must be active"});if(dto.ManagerId.HasValue&&!await _db.Users.AnyAsync(x=>x.UserId==dto.ManagerId&&x.Role=="Manager"&&x.IsActive))return BadRequest(new{message="Project manager must be an active Manager"});return null;}
 private async Task<IActionResult> AssignInternal(int projectId,int employeeId){var managerId=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);var project=await _db.Projects.FindAsync(projectId);if(project is null)return NotFound(new{message="Project not found"});if(project.IsArchived)return Conflict(new{message="Archived projects cannot receive assignments"});if(project.ManagerId!=managerId)return Forbid();var employee=await _db.Users.FirstOrDefaultAsync(x=>x.UserId==employeeId&&x.Role=="Employee"&&x.IsActive);if(employee is null)return BadRequest(new{message="Assignee must be an active Employee"});if(await _db.ProjectAssignments.AnyAsync(x=>x.ProjectId==projectId&&x.UserId==employeeId))return Conflict(new{message="Employee is already assigned"});_db.ProjectAssignments.Add(new ProjectAssignment{ProjectId=projectId,UserId=employeeId,AssignedAt=DateTime.UtcNow});await _db.SaveChangesAsync();await _audit.RecordAsync("ProjectEmployeeAssigned","Project",projectId.ToString(),safeMetadata:new{employeeId});return Ok(new{message="Employee assigned"});}
}